#pragma once#include <stdlib.h>enum EPackageType{  epkUndefined,  //в сервер  epkInitialize,  //конкретным реализациям  epkAfterInit,  epkAfterRestored,  epkCalcStep,  epkSaveRSUParams,  epkRestoreRSUParams,  epkSaveRSUState,  epkRestoreRSUState,  epkShowObject,};//#pragma warning( push )//#pragma warning( disable : 4200)struct SCopyDataHeader{  SCopyDataHeader() : type( epkUndefined )  {    fullSize = sizeof(*this);  }  EPackageType type;  DWORD fullSize;  //BYTE data[0];};//#pragma warning( pop )struct SInitialModel : SCopyDataHeader{  SInitialModel()  {    ZeroMemory( this, sizeof(*this) );    type = epkInitialize;    fullSize = sizeof(*this);  }  char szImplementation[32];  char szName[512];};struct SSaveRestoreSP : SCopyDataHeader{  SSaveRestoreSP()  {    ZeroMemory( this, sizeof(*this) );    type = epkUndefined;    fullSize = sizeof(*this);  }  char szPath[_MAX_PATH];};struct SShowObject : SCopyDataHeader{  SShowObject()  {    ZeroMemory( this, sizeof(*this) );    type = epkShowObject;    fullSize = sizeof(*this);  }  char szName[_MAX_PATH];};